import {
  Suspense,
  lazy,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "./strings/ja";
import { hsLightTheme, hsDarkTheme } from "./theme/fluentTheme";
import { useThemeMode } from "./theme/useThemeMode";
import { AppShell } from "./components/AppShell";
import { TitleBar } from "./components/TitleBar";
import { CommandBar } from "./components/CommandBar";
import { WaveformView } from "./components/WaveformView";
import { ScoreWorkspace } from "./components/ScoreWorkspace";
import { PropertiesPanel } from "./components/PropertiesPanel";
import { TransportBar } from "./components/TransportBar";
import { StatusBar } from "./components/StatusBar";
import { SettingsView } from "./components/SettingsView";
import type { PitchView } from "./components/PitchSegmented";
import {
  createCommandRegistry,
  createCommandSurface,
  type CommandContext,
  type CommandSnapshot,
} from "./commands/registry";
import { KeyboardDispatcher } from "./keyboard/dispatcher";
import { useCommandKeyboard } from "./keyboard/useCommandKeyboard";
import { cycleFocusZone, focusZone } from "./focus/zones";
import { getShellInfo } from "./tauri/bridge";
import {
  regionVisibility,
  commandStateFor,
  SCREEN_STATES,
  type ScreenState,
} from "./workspace/screen";
import { NO_SELECTION } from "./workspace/inspector";
import { useWorkspaceLayout } from "./workspace/layout";
import { initWindowGeometryPersistence } from "./workspace/windowGeometry";

type View = "workspace" | "settings";

/** "#/dev/gallery" — dev-only internal component gallery (UI-010). */
const GALLERY_HASH = "#/dev/gallery";
/** "#/dev/state/<screen>" — dev-only screen-state override so the
 *  responsive layout can be verified in every machine state (§27) before
 *  the real audio/score features land. No-op in packaged builds. */
const STATE_HASH_PREFIX = "#/dev/state/";
// Lazy so the gallery (and its Fluent imports) stay out of the prod bundle.
const DevGallery = import.meta.env.DEV
  ? lazy(() => import("./dev/Gallery"))
  : null;

function screenFromHash(hash: string): ScreenState | null {
  if (!import.meta.env.DEV || !hash.startsWith(STATE_HASH_PREFIX)) return null;
  const name = hash.slice(STATE_HASH_PREFIX.length);
  return (SCREEN_STATES as readonly string[]).includes(name)
    ? (name as ScreenState)
    : null;
}

/** Japanese display name for a focus zone (for status announcements). */
function zoneName(id: string): string {
  const names: Record<string, string> = ja.commandFeedback.zoneNames;
  return names[id] ?? id;
}

/**
 * HornScribe workspace shell (UI-011) driven by the UI-012 command
 * architecture (GUI_UX_SPEC §2/§21/§22/§23/§27). Information architecture:
 * single workspace, score is primary, properties collapse before the score
 * narrows, command overflow instead of horizontal scrolling, layout state
 * restored across restarts.
 *
 * The screen-state machine (§27) feeds the CommandSnapshot, so every
 * surface — command bar, transport, keyboard — agrees on enablement:
 * EMPTY mounts only 開く-level shell actions; 採譜 needs audio and is
 * disabled while transcribing; 要確認/書き出し need a score.
 */
export default function App() {
  const { mode, resolved, select } = useThemeMode();
  const [view, setView] = useState<View>("workspace");
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [statusMessage, setStatusMessage] = useState<string>(ja.status.ready);
  const [shellDetail, setShellDetail] = useState<string | undefined>(
    ja.status.shellInfoLoading,
  );
  const [hash, setHash] = useState(() => window.location.hash);
  // Screen state machine (§27). The live app is EMPTY until file/engine
  // plumbing lands; dev builds can override via "#/dev/state/<name>".
  const [screen, setScreen] = useState<ScreenState>("empty");
  const layout = useWorkspaceLayout();

  const regions = regionVisibility(screen);
  // Inspector contract: no selection model exists yet (UI-003+); the panel
  // renders the "none" body when opened manually.
  const inspector = NO_SELECTION;
  const propertiesVisible = regions.properties && layout.propertiesOpen;
  // Dev-state placeholder: REVIEWING pretends a score with open issues so
  // the 要確認 surfaces exercise their populated rendering.
  const reviewCount = screen === "reviewing" ? 12 : 0;

  // The registry is static: predicates read the snapshot, not React state.
  const registry = useMemo(() => createCommandRegistry(), []);

  // Screen machine → command snapshot (§23). Playback/undo/selection stay
  // false until their feature issues land; isTranscribing is the field that
  // keeps score-writing commands disabled while a transcription runs (§5).
  const snapshot = useMemo<CommandSnapshot>(
    () => ({
      ...commandStateFor(screen),
      isPlaying: false,
      loopEnabled: false,
      pitch,
      canUndo: false,
      canRedo: false,
      hasSelection: false,
      reviewCount,
      view,
    }),
    [screen, pitch, reviewCount, view],
  );

  const ctx = useMemo<CommandContext>(
    () => ({
      openAudio: () => setStatusMessage(ja.status.spikeNoFileOpen),
      transcribe: () => setStatusMessage(ja.commandFeedback.notImplemented),
      togglePlayPause: () =>
        setStatusMessage(ja.commandFeedback.notImplemented),
      stop: () => setStatusMessage(ja.commandFeedback.notImplemented),
      jumpBack: () => setStatusMessage(ja.commandFeedback.notImplemented),
      jumpForward: () => setStatusMessage(ja.commandFeedback.notImplemented),
      seekToStart: () => setStatusMessage(ja.commandFeedback.notImplemented),
      seekToEnd: () => setStatusMessage(ja.commandFeedback.notImplemented),
      toggleLoop: () => setStatusMessage(ja.commandFeedback.notImplemented),
      setPitchView: (v) => {
        setPitch(v);
        setStatusMessage(
          v === "concert"
            ? ja.commandFeedback.pitchConcert
            : ja.commandFeedback.pitchHornF,
        );
      },
      openReview: () => setStatusMessage(ja.commandFeedback.notImplemented),
      reviewNext: () => setStatusMessage(ja.commandFeedback.notImplemented),
      reviewPrevious: () =>
        setStatusMessage(ja.commandFeedback.notImplemented),
      undo: () => setStatusMessage(ja.commandFeedback.notImplemented),
      redo: () => setStatusMessage(ja.commandFeedback.notImplemented),
      openExport: () => setStatusMessage(ja.commandFeedback.notImplemented),
      zoomScoreIn: () => setStatusMessage(ja.commandFeedback.notImplemented),
      zoomScoreOut: () => setStatusMessage(ja.commandFeedback.notImplemented),
      zoomScoreFit: () => setStatusMessage(ja.commandFeedback.notImplemented),
      clearSelection: () =>
        setStatusMessage(ja.commandFeedback.notImplemented),
      openSettings: () => setView("settings"),
      // F6 / Shift+F6 region cycling (§22) — owned by focus/zones.ts; these
      // are the only fully-working transport-independent commands so far.
      focusNextRegion: () => {
        const zone = cycleFocusZone(1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      focusPreviousRegion: () => {
        const zone = cycleFocusZone(-1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      announce: setStatusMessage,
    }),
    [],
  );

  // The dispatcher reads the snapshot lazily per key event, so it must see
  // the latest render's value even though the listener is stable.
  const snapshotRef = useRef(snapshot);
  snapshotRef.current = snapshot;
  const dispatcher = useMemo(
    () =>
      new KeyboardDispatcher({
        registry,
        getSnapshot: () => snapshotRef.current,
        context: ctx,
      }),
    [registry, ctx],
  );
  useCommandKeyboard(dispatcher);

  // One render-scoped invocation surface shared by command bar, transport
  // and any other component — buttons never call services directly.
  const commands = useMemo(
    () => createCommandSurface(registry, ctx, snapshot),
    [registry, ctx, snapshot],
  );

  // Closing the panel returns focus to the score region when the focus was
  // inside the panel (§22 focus discipline); if it was closed from the
  // overflow menu, focus stays where it is.
  const closeProperties = useCallback(() => {
    const focusInside =
      document
        .querySelector('.hs-properties')
        ?.contains(document.activeElement) ?? false;
    layout.setPropertiesOpen(false);
    if (focusInside) {
      requestAnimationFrame(() => focusZone("score"));
    }
  }, [layout]);

  // 採譜 / キャンセル share one callback: the command is disabled while a
  // transcription runs (§5), so the cancel affordance falls through to an
  // honest "not implemented yet" announcement instead of silently no-oping.
  const transcribeClicked = useCallback(() => {
    if (!commands.invoke("score.transcribe")) {
      setStatusMessage(ja.commandFeedback.notImplemented);
    }
  }, [commands]);

  // Hash routing: internal dev gallery + dev screen-state override. The
  // product shell is a single workspace (§2), not a page router.
  useEffect(() => {
    const onHashChange = () => {
      const h = window.location.hash;
      setHash(h);
      const forced = screenFromHash(h);
      if (forced) {
        setScreen(forced);
        setView("workspace");
      }
    };
    window.addEventListener("hashchange", onHashChange);
    onHashChange();
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  // §26 session restore: window geometry (size/position) persists across
  // restarts; panel sizes/visibility persist via useWorkspaceLayout.
  useEffect(() => {
    let alive = true;
    let unlisten: (() => void) | undefined;
    void initWindowGeometryPersistence().then((u) => {
      if (alive) unlisten = u;
      else u();
    });
    return () => {
      alive = false;
      unlisten?.();
    };
  }, []);

  // Prove the JS↔Rust IPC channel early; populates the status area.
  useEffect(() => {
    let alive = true;
    getShellInfo().then((info) => {
      if (!alive) return;
      setShellDetail(
        info ? `v${info.version}` : undefined, // browser dev: no shell info
      );
      setStatusMessage(ja.status.ready);
    });
    return () => {
      alive = false;
    };
  }, []);

  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;
  // Dev-only route: the gallery renders in place of the shell and never
  // appears in product navigation.
  const showGallery = DevGallery != null && hash === GALLERY_HASH;

  return (
    // .hs-provider fixes the UI-009 latent bug: the FluentProvider wrapper
    // div had no definite height, so `height:100%` on .hs-shell collapsed
    // to content height. The provider now owns the full viewport.
    <FluentProvider theme={theme} className="hs-provider">
      {showGallery ? (
        <Suspense fallback={null}>
          <DevGallery themeMode={mode} onThemeMode={select} />
        </Suspense>
      ) : (
        <AppShell>
          <TitleBar />
          {view === "settings" ? (
            <div className="hs-settings-wrap">
              <SettingsView
                themeMode={mode}
                onThemeMode={select}
                onBack={() => setView("workspace")}
              />
            </div>
          ) : (
            <>
              <CommandBar
                commands={commands}
                pitch={pitch}
                screen={screen}
                reviewCount={reviewCount}
                compact={layout.breakpoint === "compact"}
                propertiesOpen={layout.propertiesOpen}
                onToggleProperties={() =>
                  layout.setPropertiesOpen(!layout.propertiesOpen)
                }
              />
              {regions.waveform ? (
                <WaveformView
                  height={layout.waveformHeight}
                  min={layout.waveformMin}
                  max={layout.waveformMax}
                  onResize={layout.requestWaveformHeight}
                  onReset={layout.resetWaveformHeight}
                />
              ) : null}
              <div className="hs-main">
                <ScoreWorkspace
                  screen={screen}
                  onOpenAudio={() => commands.invoke("file.openAudio")}
                  onTranscribe={transcribeClicked}
                />
                {propertiesVisible ? (
                  <PropertiesPanel
                    content={inspector}
                    width={layout.propertiesWidth}
                    min={layout.propertiesMin}
                    max={layout.propertiesMax}
                    overlay={layout.breakpoint === "compact"}
                    onResize={layout.requestPropertiesWidth}
                    onReset={layout.resetPropertiesWidth}
                    onClose={closeProperties}
                  />
                ) : null}
              </div>
              {regions.transport ? <TransportBar commands={commands} /> : null}
            </>
          )}
          <StatusBar message={statusMessage} detail={shellDetail} />
        </AppShell>
      )}
    </FluentProvider>
  );
}

import type { ReactNode } from "react";

/**
 * AppShell — fixed workspace grid (GUI_UX_SPEC §2).
 * Row order = focus/scan order: title, command bar, waveform, workspace,
 * transport, status.
 *
 * F6 / Shift+F6 region cycling is owned by the UI-012 architecture: regions
 * self-identify via `data-hs-focus-zone` (src/focus/zones.ts) and the
 * nav.nextRegion / nav.previousRegion commands drive the cycle through the
 * central keyboard dispatcher. This component owns no keydown handler.
 */
export function AppShell({ children }: { children: ReactNode }) {
  return <div className="hs-shell">{children}</div>;
}

import { Toolbar, ToolbarButton, Tooltip } from "@fluentui/react-components";
import {
  FolderOpen24Regular,
  Play24Regular,
  CheckmarkCircle24Regular,
  ArrowExportUp24Regular,
  Settings24Regular,
  MoreHorizontal24Regular,
  PanelRight24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { CommandSurface } from "../commands/registry";
import { HsMenu, type HsMenuItem } from "./primitives/Menu";
import { PitchSegmented, type PitchView } from "./PitchSegmented";
import type { ScreenState } from "../workspace/screen";

/** Tooltip text: Japanese title plus its canonical shortcut, e.g.
 *  「書き出し（Ctrl+E）」 — shortcut hinting is spec'd on §9 controls. */
function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Command bar (GUI_UX_SPEC §16, DESIGN_SYSTEM §10).
 * Left: project actions. Center: pitch selector. Right: 要確認/書き出し/設定/overflow.
 * Never scrolls; at <1600px secondary labels collapse to icon+tooltip
 * (§21), at <1200px 設定 moves into the overflow menu. The menu always
 * carries the properties show/close toggle so the panel stays reachable.
 *
 * EMPTY state (§3) hides every score/audio command — only 開く, 設定 and
 * the overflow menu render, so the empty surface stays free of score tools.
 *
 * Every action routes through the command surface (§23): enabled state,
 * Japanese label and shortcut all come from the registry, so the button,
 * the menu item and the keyboard binding can never disagree.
 */
export function CommandBar({
  commands,
  pitch,
  screen,
  reviewCount,
  compact,
  propertiesOpen,
  onToggleProperties,
}: {
  commands: CommandSurface;
  pitch: PitchView;
  screen: ScreenState;
  reviewCount: number;
  /** <1200px breakpoint — 設定 lives in the overflow menu instead. */
  compact: boolean;
  propertiesOpen: boolean;
  onToggleProperties(): void;
}) {
  // 採譜 ↔ 採譜し直す — same command slot, label follows score presence
  // (the registry hides retranscribe until a score exists).
  const transcribeId = "score.transcribe";
  const retranscribeId = "score.retranscribe";
  const transcribe = commands.isVisible(retranscribeId)
    ? retranscribeId
    : transcribeId;

  const onPitch = (v: PitchView) =>
    commands.invoke(v === "concert" ? "view.concertPitch" : "view.hornF");

  const loaded = screen !== "empty";
  const hasScore =
    screen === "scoreReady" || screen === "reviewing" || screen === "exporting";
  const transcribeTooltip = hasScore
    ? ja.commandBar.retranscribeTooltip
    : ja.commandBar.transcribeTooltip;
  const reviewLabel =
    reviewCount > 0
      ? ja.commandBar.reviewWithCount.replace("{count}", String(reviewCount))
      : ja.commandBar.review;

  const overflowItems: HsMenuItem[] = [
    ...(compact
      ? [
          {
            key: "settings",
            label: commands.title("app.settings"),
            icon: <Settings24Regular />,
          } satisfies HsMenuItem,
        ]
      : []),
    {
      key: "properties",
      label: propertiesOpen ? ja.properties.close : ja.properties.show,
      icon: <PanelRight24Regular />,
    },
  ];

  return (
    <Toolbar
      className="hs-commandbar"
      aria-label={ja.commandBar.regionLabel}
      data-hs-focus-zone="commandbar"
      tabIndex={-1}
    >
      <Tooltip content={ja.commandBar.openTooltip} relationship="label">
        <ToolbarButton
          icon={<FolderOpen24Regular />}
          disabled={!commands.isEnabled("file.openAudio")}
          aria-keyshortcuts="Control+O"
          onClick={() => commands.invoke("file.openAudio")}
        >
          <span className="hs-commandbar__label">{ja.commandBar.openLabel}</span>
        </ToolbarButton>
      </Tooltip>
      {loaded ? (
        <Tooltip content={transcribeTooltip} relationship="label">
          <ToolbarButton
            icon={<Play24Regular />}
            disabled={!commands.isEnabled(transcribe)}
            appearance="primary"
            onClick={() => commands.invoke(transcribe)}
          >
            <span className="hs-commandbar__label">
              {commands.title(transcribe)}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}

      {loaded ? <span className="hs-commandbar__spacer" /> : null}
      {loaded ? <PitchSegmented value={pitch} onChange={onPitch} /> : null}
      <span className="hs-commandbar__spacer" />

      {loaded ? (
        <Tooltip content={reviewLabel} relationship="label">
          <ToolbarButton
            icon={<CheckmarkCircle24Regular />}
            disabled={!commands.isEnabled("review.open")}
            onClick={() => commands.invoke("review.open")}
          >
            <span className="hs-commandbar__label">{reviewLabel}</span>
          </ToolbarButton>
        </Tooltip>
      ) : null}
      {loaded ? (
        <Tooltip
          content={withShortcut(
            ja.commandBar.exportTooltip,
            commands.shortcutLabel("export.open"),
          )}
          relationship="label"
        >
          <ToolbarButton
            icon={<ArrowExportUp24Regular />}
            disabled={!commands.isEnabled("export.open")}
            aria-keyshortcuts="Control+E"
            onClick={() => commands.invoke("export.open")}
          >
            <span className="hs-commandbar__label">
              {commands.title("export.open")}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}
      {!compact && commands.isEnabled("app.settings") ? (
        <Tooltip
          content={commands.title("app.settings")}
          relationship="label"
        >
          <ToolbarButton
            icon={<Settings24Regular />}
            onClick={() => commands.invoke("app.settings")}
          />
        </Tooltip>
      ) : null}
      <HsMenu
        trigger={
          <ToolbarButton
            icon={<MoreHorizontal24Regular />}
            aria-label={ja.commandBar.overflow}
          />
        }
        items={overflowItems}
        ariaLabel={ja.commandBar.overflow}
        onSelect={(key) => {
          if (key === "settings") commands.invoke("app.settings");
          else if (key === "properties") onToggleProperties();
        }}
      />
    </Toolbar>
  );
}

import { mergeClasses } from "@fluentui/react-components";
import { Dismiss16Regular } from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsIconButton } from "./primitives/IconButton";
import type { InspectorContent } from "../workspace/inspector";
import { startPointerResize } from "../workspace/layout";

/**
 * Properties inspector (GUI_UX_SPEC §6, §21; inspector contract in
 * workspace/inspector.ts).
 *
 * - Docked on the right at ≥1200px; below that it renders as a non-modal
 *   overlay drawer so the score keeps priority (§21).
 * - User-closable (acceptance: properties can be closed); the command-bar
 *   overflow menu reopens it. With no selection it shows only the
 *   placeholder body — feature inspectors (note/range) slot into the
 *   `content` contract, not into this file.
 * - Left-edge separator resizes within the breakpoint clamps.
 */
export function PropertiesPanel({
  content,
  width,
  min,
  max,
  overlay,
  onResize,
  onReset,
  onClose,
}: {
  content: InspectorContent;
  width: number;
  min: number;
  max: number;
  /** <1200px: overlay the score instead of docking beside it. */
  overlay: boolean;
  onResize(px: number): void;
  onReset(): void;
  onClose(): void;
}) {
  return (
    <aside
      className={mergeClasses(
        "hs-properties",
        overlay && "hs-properties--overlay",
      )}
      style={{ width }}
      aria-label={ja.properties.regionLabel}
      data-hs-focus-zone="properties"
      tabIndex={0}
    >
      <div className="hs-properties__frame">
        <header className="hs-properties__header">
          <h2 className="hs-properties__title">{ja.properties.title}</h2>
          <HsIconButton
            label={ja.properties.close}
            icon={<Dismiss16Regular />}
            size="small"
            onClick={onClose}
          />
        </header>
        <div className="hs-properties__body" data-inspector={content.kind}>
          {/* Inspector contract: `content` resolves the selection → body.
              kind "note"/"range" get their feature inspectors later; the
              shell guarantees the panel chrome either way. */}
          <p className="hs-properties__placeholder">
            {ja.properties.placeholder}
          </p>
        </div>
      </div>
      <div
        className="hs-properties__resizer"
        role="separator"
        aria-orientation="vertical"
        aria-label={ja.properties.resizeHandle}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={width}
        tabIndex={0}
        onPointerDown={(e) => {
          const startW = width;
          const startX = e.clientX;
          // Panel is right-anchored: dragging left grows it.
          startPointerResize(e, onResize, (x) => startW + (startX - x));
        }}
        onKeyDown={(e) => {
          // ← grows (panel expands leftward), → shrinks.
          const step = e.key === "ArrowLeft" ? 8 : e.key === "ArrowRight" ? -8 : null;
          if (step != null) {
            e.preventDefault();
            onResize(width + step);
          }
        }}
        onDoubleClick={onReset}
      />
    </aside>
  );
}

import { useState } from "react";
import { mergeClasses } from "@fluentui/react-components";
import { FolderOpen24Regular, Play24Regular } from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "./primitives/Button";
import { HsProgress } from "./primitives/Progress";
import type { ScreenState } from "../workspace/screen";

/**
 * Score workspace (GUI_UX_SPEC §3/§4/§5/§6, §27 screen state machine).
 * The score is always the primary surface — properties collapse before it
 * narrows (§21). Content is state-driven:
 *   empty        → drop target + single open CTA, nothing else (§3)
 *   audioReady   → "まだ楽譜はありません" + 採譜を開始 (§4)
 *   transcribing → stage list + honest indeterminate progress (§5)
 *   scoreReady+  → score paper placeholder (real rendering is UI-003)
 */
export function ScoreWorkspace({
  screen,
  onOpenAudio,
  onTranscribe,
}: {
  screen: ScreenState;
  onOpenAudio(): void;
  onTranscribe(): void;
}) {
  const [dragOver, setDragOver] = useState(false);
  return (
    <main
      className={mergeClasses("hs-score", dragOver && "hs-score--dragover")}
      role="region"
      aria-label={ja.score.regionLabel}
      data-hs-focus-zone="score"
      tabIndex={0}
      onDragOver={(e) => {
        e.preventDefault();
        setDragOver(true);
      }}
      onDragLeave={() => setDragOver(false)}
      onDrop={(e) => {
        // Browser-dev affordance: Tauri delivers file drops natively; in a
        // plain webview this still routes to the open command path.
        e.preventDefault();
        setDragOver(false);
        onOpenAudio();
      }}
    >
      {screen === "empty" ? (
        <div className="hs-empty">
          <p className="hs-empty__title">{ja.emptyState.title}</p>
          <p className="hs-empty__or">{ja.emptyState.or}</p>
          <HsButton
            variant="primary"
            size="large"
            icon={<FolderOpen24Regular />}
            onClick={onOpenAudio}
          >
            {ja.emptyState.open}
          </HsButton>
          <p className="hs-empty__formats">{ja.emptyState.formats}</p>
          <p className="hs-empty__privacy">{ja.emptyState.privacy}</p>
        </div>
      ) : screen === "audioReady" ? (
        <div className="hs-empty">
          <p className="hs-score__empty-title">{ja.score.empty}</p>
          <HsButton
            variant="primary"
            size="large"
            icon={<Play24Regular />}
            onClick={onTranscribe}
          >
            {ja.score.transcribeStart}
          </HsButton>
        </div>
      ) : screen === "transcribing" ? (
        <div className="hs-transcribing" role="status">
          <p className="hs-transcribing__title">{ja.transcription.title}</p>
          <ul className="hs-stage-list">
            <li className="hs-stage hs-stage--done">
              <span className="hs-stage__icon" aria-hidden="true">
                ✓
              </span>
              {ja.transcription.stageDone}
            </li>
            <li className="hs-stage hs-stage--active">
              <span className="hs-stage__icon" aria-hidden="true">
                ●
              </span>
              {ja.transcription.stageActive}
            </li>
            <li className="hs-stage">
              <span className="hs-stage__icon" aria-hidden="true">
                ○
              </span>
              {ja.transcription.stageRhythm}
            </li>
            <li className="hs-stage">
              <span className="hs-stage__icon" aria-hidden="true">
                ○
              </span>
              {ja.transcription.stageScore}
            </li>
            <li className="hs-stage">
              <span className="hs-stage__icon" aria-hidden="true">
                ○
              </span>
              {ja.transcription.stagePrepare}
            </li>
          </ul>
          {/* §5: indeterminate while no honest percentage exists. */}
          <HsProgress label={ja.transcription.title} />
          <HsButton variant="secondary" onClick={onTranscribe}>
            {ja.transcription.cancel}
          </HsButton>
        </div>
      ) : (
        <div className="hs-score-paper" aria-hidden="true">
          <span className="hs-score-paper__placeholder">
            {ja.score.placeholder}
          </span>
        </div>
      )}
    </main>
  );
}

import { Toolbar, ToolbarButton, Tooltip } from "@fluentui/react-components";
import {
  Previous24Regular,
  Rewind24Regular,
  Play24Regular,
  Stop24Regular,
  FastForward24Regular,
  Next24Regular,
  ArrowRepeatAll24Regular,
  SlideTextSparkle24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { CommandSurface } from "../commands/registry";

function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Transport bar (GUI_UX_SPEC §9). Mounted only once audio exists; every
 * control stays disabled while a command's snapshot predicate is false.
 *
 * All actions dispatch through the command surface (§23) — the Space key,
 * this button and a future menu item are the same command, so enabled
 * state and Japanese labels can never disagree across surfaces.
 */
export function TransportBar({ commands }: { commands: CommandSurface }) {
  // All transport commands share the hasAudio gate (see definitions).
  const enabled = commands.isEnabled("transport.playPause");
  return (
    <Toolbar
      className="hs-transport"
      aria-label={ja.transport.regionLabel}
      data-hs-focus-zone="transport"
      tabIndex={-1}
    >
      <Tooltip
        content={withShortcut(
          commands.title("transport.seekStart"),
          commands.shortcutLabel("transport.seekStart"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Previous24Regular />}
          aria-label={commands.title("transport.seekStart")}
          aria-keyshortcuts="Home"
          disabled={!commands.isEnabled("transport.seekStart")}
          onClick={() => commands.invoke("transport.seekStart")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.jumpBack"),
          commands.shortcutLabel("transport.jumpBack"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Rewind24Regular />}
          aria-label={commands.title("transport.jumpBack")}
          aria-keyshortcuts="J"
          disabled={!commands.isEnabled("transport.jumpBack")}
          onClick={() => commands.invoke("transport.jumpBack")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.playPause"),
          commands.shortcutLabel("transport.playPause"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Play24Regular />}
          aria-label={commands.title("transport.playPause")}
          aria-keyshortcuts="Space K"
          disabled={!commands.isEnabled("transport.playPause")}
          appearance="primary"
          onClick={() => commands.invoke("transport.playPause")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.stop"),
          commands.shortcutLabel("transport.stop"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Stop24Regular />}
          aria-label={commands.title("transport.stop")}
          aria-keyshortcuts="Shift+Space"
          disabled={!commands.isEnabled("transport.stop")}
          onClick={() => commands.invoke("transport.stop")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.jumpForward"),
          commands.shortcutLabel("transport.jumpForward"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<FastForward24Regular />}
          aria-label={commands.title("transport.jumpForward")}
          aria-keyshortcuts="L"
          disabled={!commands.isEnabled("transport.jumpForward")}
          onClick={() => commands.invoke("transport.jumpForward")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.seekEnd"),
          commands.shortcutLabel("transport.seekEnd"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Next24Regular />}
          aria-label={commands.title("transport.seekEnd")}
          aria-keyshortcuts="End"
          disabled={!commands.isEnabled("transport.seekEnd")}
          onClick={() => commands.invoke("transport.seekEnd")}
        />
      </Tooltip>
      <span className="hs-transport__time" aria-label={ja.transport.position}>
        {ja.time.zero} / {ja.time.zeroTotal}
      </span>

      <span className="hs-transport__spacer" />

      <Tooltip content={`${ja.transport.rate} 1.0×`} relationship="label">
        <ToolbarButton disabled={!enabled}>1.0×</ToolbarButton>
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.toggleLoop"),
          commands.shortcutLabel("transport.toggleLoop"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<ArrowRepeatAll24Regular />}
          aria-label={commands.title("transport.toggleLoop")}
          aria-keyshortcuts="Control+L"
          disabled={!commands.isEnabled("transport.toggleLoop")}
          onClick={() => commands.invoke("transport.toggleLoop")}
        />
      </Tooltip>
      <Tooltip content={ja.transport.follow} relationship="label">
        <ToolbarButton
          icon={<SlideTextSparkle24Regular />}
          aria-label={ja.transport.follow}
          disabled={!enabled}
        />
      </Tooltip>
    </Toolbar>
  );
}

import { ja } from "../strings/ja";
import { resizeKeyDelta, startPointerResize } from "../workspace/layout";

/**
 * Waveform / timeline region (GUI_UX_SPEC §2, §8).
 * Height is user-resizable: 64px minimum up to ≈35% of the work area, and
 * always smaller than the score. The bottom-edge separator supports pointer
 * drag, ArrowUp/ArrowDown (±8px) and double-click reset — deterministic
 * clamps live in workspace/layout.ts.
 */
export function WaveformView({
  height,
  min,
  max,
  onResize,
  onReset,
}: {
  height: number;
  min: number;
  max: number;
  onResize(px: number): void;
  onReset(): void;
}) {
  return (
    <div
      className="hs-waveform"
      role="region"
      aria-label={ja.waveform.regionLabel}
      data-hs-focus-zone="waveform"
      tabIndex={0}
      style={{ height }}
    >
      <span className="hs-waveform__placeholder">
        {ja.waveform.placeholder}
      </span>
      <div
        className="hs-waveform__resizer"
        role="separator"
        aria-orientation="horizontal"
        aria-label={ja.waveform.resizeHandle}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={height}
        tabIndex={0}
        onPointerDown={(e) => {
          const startH = height;
          const startY = e.clientY;
          startPointerResize(e, onResize, (_x, y) => startH + (y - startY));
        }}
        onKeyDown={(e) => {
          const next = resizeKeyDelta(e, height);
          if (next != null) {
            e.preventDefault();
            onResize(next);
          }
        }}
        onDoubleClick={onReset}
      />
    </div>
  );
}

/**
 * HornScribe app shell layout + token consumers.
 * Colors come only from --hs-* semantic tokens (tokens.css).
 */

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-body);
  color: var(--hs-text-primary);
  background: var(--hs-surface-app);
  overflow: hidden;
}

/* UI-009 latent bug, fixed for the real shell (UI-011): FluentProvider
   renders a wrapper div between #root and the shell; without a definite
   height the `height:100%` grid below collapsed to content height. */
.hs-provider {
  height: 100%;
}

/* ---- Visible keyboard focus (DESIGN_SYSTEM §16) ----
   2px+, distinct from adjacent surface; Fluent v9 components draw their own
   compatible focus ring, this guarantees the same contract for every other
   focusable region (waveform, score surface, segmented control, links). */
:focus-visible {
  outline: var(--hs-focus-width) solid var(--hs-focus);
  outline-offset: var(--hs-focus-offset);
  border-radius: var(--hs-radius-input);
}
/* Never remove the outline without a replacement. */
:focus:not(:focus-visible) {
  outline: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================ App shell ============================ */
/* GUI_UX_SPEC §2 information architecture:
   title bar → command bar → waveform → score workspace → transport → status */
.hs-shell {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto;
  grid-template-areas:
    "titlebar"
    "commandbar"
    "waveform"
    "main"
    "transport"
    "statusbar";
  height: 100%;
  min-width: 0;
  /* §21: <1100px is unsupported — the native window minimum (1100×640 in
     tauri.conf.json) stops resizing first; this floor mirrors it so a
     browser dev viewport can never compress the layout below spec. With
     body overflow:hidden the excess clips instead of scrolling — there is
     deliberately no app-level horizontal scroll. */
  min-width: 1100px;
  min-height: 640px;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Title bar area (in-app; native window chrome is kept) ---- */
.hs-titlebar {
  grid-area: titlebar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 32px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-titlebar__app {
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-titlebar__doc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Command bar (DESIGN_SYSTEM §10: ~44px, never scrolls) ---- */
.hs-commandbar {
  grid-area: commandbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 44px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  overflow: hidden;
  white-space: nowrap;
}
/* Buttons never shrink/clip — below 1600px secondary labels hide instead
   (§21 icon化), below 1200px 設定 moves to the overflow menu. */
.hs-commandbar .fui-ToolbarButton,
.hs-commandbar .fui-Button {
  flex-shrink: 0;
}
/* 1200–1599px: secondary commands render icon-only; their Tooltip carries
   the full Japanese label (§24). Labels are hidden, never ellipsized. */
@media (max-width: 1599px) {
  .hs-commandbar__label {
    display: none;
  }
}
.hs-commandbar__spacer {
  flex: 1 1 auto;
  min-width: var(--hs-space-sm);
}

/* ---- Segmented control (DESIGN_SYSTEM §11: text labels, never icon-only) ---- */
.hs-segmented {
  display: inline-flex;
  flex: 0 0 auto;
  border: 1px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-input);
  overflow: hidden;
  background: var(--hs-surface-elevated);
}
.hs-segmented__item {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--hs-text-secondary);
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-compact);
  line-height: 1;
  padding: 8px 12px;
  cursor: pointer;
  white-space: nowrap;
}
.hs-segmented__item + .hs-segmented__item {
  border-left: 1px solid var(--hs-border-subtle);
}
.hs-segmented__item:hover {
  background: var(--hs-control-hover);
}
/* selected state = fill + weight + border cues combined (§11);
   on-accent text color keeps ≥4.5:1 in both themes (dark accent is light,
   so the foreground flips to dark ink via --hs-accent-foreground). */
.hs-segmented__item[aria-checked="true"] {
  background: var(--hs-accent);
  color: var(--hs-accent-foreground);
  font-weight: var(--hs-font-weight-emphasis);
  box-shadow: inset 0 0 0 1px var(--hs-accent-pressed);
}
.hs-segmented__item:focus-visible {
  outline-offset: -2px;
}

/* ---- Waveform region (GUI_UX_SPEC §8: 96–120px standard) ----
   Height is inline (user-resizable via the bottom-edge separator);
   min/max here are the CSS backstop, JS clamps are authoritative. */
.hs-waveform {
  grid-area: waveform;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 64px;
  max-height: 35vh;
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}
.hs-waveform__resizer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 8px;
  cursor: row-resize;
  touch-action: none;
  z-index: 6;
}

/* Shared separator affordance: quiet until hover/focus (§8 elevation —
   workspace stays flat, so the grip uses a translucent accent wash). */
.hs-waveform__resizer:hover,
.hs-waveform__resizer:focus-visible,
.hs-properties__resizer:hover,
.hs-properties__resizer:focus-visible {
  background: color-mix(in srgb, var(--hs-accent) 30%, transparent);
}

/* ---- Score workspace + properties ---- */
.hs-main {
  grid-area: main;
  position: relative; /* anchor for the overlay properties drawer */
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 0;
  min-width: 0;
}

.hs-score {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-md);
  min-width: 0;
  min-height: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-score);
  color: var(--hs-text-primary);
  /* Score paper keeps a hairline radius, not decorative rounding (§7). */
  border-radius: var(--hs-radius-score-paper);
  overflow: auto;
}
.hs-score--dragover {
  outline: 2px dashed var(--hs-accent);
  outline-offset: -8px;
}
.hs-score__empty-title {
  margin: 0;
  font-size: var(--hs-font-size-title);
  font-weight: 400;
  color: var(--hs-text-primary);
}
/* Score-ready placeholder paper: bounded page shape inside the score
   surface until UI-003 renders real notation. */
.hs-score-paper {
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  flex: 1 1 auto;
  min-height: 0;
  margin: var(--hs-space-xs);
  border: 1px solid var(--hs-score-paper-border);
  border-radius: var(--hs-radius-score-paper);
  background: var(--hs-surface-score);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* ---- Transcribing state (§5): stage list + honest progress ---- */
.hs-transcribing {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-md);
  width: 100%;
  max-width: 360px;
}
.hs-transcribing__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-transcribing .hs-field {
  width: 100%;
}
.hs-stage-list {
  align-self: stretch;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--hs-space-xs);
}
.hs-stage {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}
.hs-stage--done {
  color: var(--hs-status-success);
}
.hs-stage--active {
  color: var(--hs-status-info);
  font-weight: var(--hs-font-weight-emphasis);
}
.hs-stage__icon {
  display: inline-flex;
  width: 16px;
  justify-content: center;
}

/* Properties inspector (§6, §21): docked at ≥1200px with an inline width
   inside the breakpoint clamp; <1200px it becomes a non-modal overlay
   drawer so the score keeps the workspace. */
.hs-properties {
  position: relative;
  display: flex;
  flex-direction: row;
  min-width: 0;
  min-height: 0;
  background: var(--hs-surface-panel);
  border-left: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-secondary);
}
.hs-properties--overlay {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 8;
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-sheet);
}
.hs-properties__frame {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
}
.hs-properties__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  min-height: 40px;
  padding: var(--hs-space-xs) var(--hs-space-sm) var(--hs-space-xs)
    var(--hs-space-md);
  border-bottom: 1px solid var(--hs-border-subtle);
}
.hs-properties__title {
  flex: 1 1 auto;
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-properties__body {
  flex: 1 1 auto;
  min-height: 0;
  padding: var(--hs-space-md);
  overflow: auto;
}
.hs-properties__placeholder {
  margin: 0;
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-muted);
}
.hs-properties__resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -5px;
  width: 9px;
  cursor: col-resize;
  touch-action: none;
  z-index: 6;
}
/* Panel open/close motion (§25 panel tier; reduced-motion collapses it). */
@keyframes hs-panel-in {
  from {
    transform: translateX(12px);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
.hs-properties {
  animation: hs-panel-in var(--hs-motion-panel) var(--hs-ease-decelerate);
}

/* ---- Empty state (GUI_UX_SPEC §3, §19: compact, clear CTA) ---- */
.hs-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-sm);
  text-align: center;
  max-width: 46em;
}
.hs-empty__title {
  margin: 0;
  font-size: var(--hs-font-size-display);
  font-weight: 400;
}
.hs-empty__or {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
.hs-empty__formats {
  margin: var(--hs-space-xs) 0 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-empty__privacy {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}

/* ---- Transport (GUI_UX_SPEC §9) ---- */
.hs-transport {
  grid-area: transport;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 52px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
}
.hs-transport__time {
  font-variant-numeric: tabular-nums; /* §5: timecode uses tabular numerals */
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  margin-left: var(--hs-space-sm);
  white-space: nowrap;
}
.hs-transport__spacer {
  flex: 1 1 auto;
}

/* ---- Status bar ---- */
.hs-statusbar {
  grid-area: statusbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-md);
  height: 26px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-muted);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-statusbar__message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-statusbar__spacer {
  flex: 1 1 auto;
}

/* ====================== Primitives (components/primitives) ======================
   Only --hs-* semantic tokens; raw values live exclusively in tokens.css. */

/* ---- HsButton (§9): danger re-tints the primary fill to palette red ----
   Double-class selectors keep precedence over Fluent's atomic classes. */
.hs-button.hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger);
  color: var(--hs-danger-foreground);
  border-color: transparent;
}
.hs-button.hs-button--danger:not(:disabled):hover {
  background-color: var(--hs-danger-hover);
}
.hs-button.hs-button--danger:not(:disabled):active {
  background-color: var(--hs-danger-pressed);
}
/* State changes use the fast motion tier (§18). */
.hs-button {
  transition-duration: var(--hs-motion-fast);
  transition-timing-function: var(--hs-ease-standard);
}

/* ---- Segmented control additions (§11, §17) ---- */
.hs-segmented__item:disabled {
  color: var(--hs-text-disabled);
  cursor: not-allowed;
}
.hs-segmented__item:disabled:hover {
  background: transparent;
}
.hs-segmented__item {
  transition: background-color var(--hs-motion-fast) var(--hs-ease-standard);
}

/* ---- StatusBadge / ReviewBadge (§15): tint + glyph + (review) dotted cue ---- */
.hs-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--hs-space-xs);
  padding: 1px var(--hs-space-sm);
  border-radius: var(--hs-radius-input);
  border: 1px solid transparent;
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  font-weight: var(--hs-font-weight-emphasis);
  white-space: nowrap;
  user-select: none;
}
.hs-badge__icon {
  display: inline-flex;
  font-size: 14px;
}
.hs-badge--neutral {
  color: var(--hs-text-secondary);
  background: var(--hs-status-neutral-subtle);
  border-color: color-mix(in srgb, currentColor 25%, transparent);
}
.hs-badge--info {
  color: var(--hs-status-info);
  background: var(--hs-status-info-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--success {
  color: var(--hs-status-success);
  background: var(--hs-status-success-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--warning {
  color: var(--hs-status-warning);
  background: var(--hs-status-warning-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--error {
  color: var(--hs-status-error);
  background: var(--hs-status-error-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
/* §15: the 要確認 marker adds a dotted underline — review is never red. */
.hs-badge--needs-review .hs-badge__label {
  border-bottom: 2px dotted var(--hs-review-marker);
}

/* ---- HsPanel (§8): flat separation by border; elevated for floats ---- */
.hs-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--hs-surface-panel);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  color: var(--hs-text-primary);
}
.hs-panel--elevated {
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-popover);
}
.hs-panel__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  padding: var(--hs-space-sm) var(--hs-space-ms);
  border-bottom: 1px solid var(--hs-border-subtle);
  min-height: 40px;
}
.hs-panel__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  line-height: var(--hs-line-height-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-panel__header-spacer {
  flex: 1 1 auto;
}
.hs-panel__body {
  padding: var(--hs-space-md);
  min-width: 0;
}
.hs-panel__body--flush {
  padding: 0;
}

/* ---- HsSlider: track + tabular readout (§5) ---- */
.hs-slider {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
}
.hs-slider .fui-Slider {
  flex: 1 1 auto;
}
.hs-slider__value {
  flex: 0 0 auto;
  min-width: 3.5em;
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}

/* ---- Settings (auxiliary screen, §18): replaces the workspace rows ---- */
.hs-settings-wrap {
  grid-row: commandbar / transport; /* spans commandbar…main rows */
  display: flex;
  min-height: 0;
  min-width: 0;
}
.hs-settings {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-app);
  overflow: auto;
}
.hs-settings__title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-title);
  font-weight: 600;
}
/* Section chrome (border / radius / padding) comes from the HsPanel
   primitive; this class only constrains width and rhythm. */
.hs-settings__section {
  margin: 0 0 var(--hs-space-lg);
  max-width: 560px;
}
.hs-settings__note {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

import { invoke } from "@tauri-apps/api/core";
import {
  getCurrentWindow,
  LogicalPosition,
  LogicalSize,
} from "@tauri-apps/api/window";

/**
 * Shell↔Rust boundary.
 *
 * App-defined commands are invoked over Tauri's built-in IPC channel and are
 * NOT governed by capabilities/ACL (those apply to plugin/core commands).
 * No plugin permissions are required for `shell_info`.
 */
export interface ShellInfo {
  appName: string;
  version: string;
  rustTargetEnv: string;
}

/**
 * Returns null instead of throwing when the app runs outside the Tauri
 * webview (e.g. plain `vite dev` in a browser) so the shell still renders.
 */
export async function getShellInfo(): Promise<ShellInfo | null> {
  try {
    return await invoke<ShellInfo>("shell_info");
  } catch {
    return null;
  }
}

/**
 * Window geometry in *logical* px (GUI_UX_SPEC §26 session restore).
 * All helpers return null / no-op outside the Tauri webview or when the
 * capability ACL denies the call, so browser dev sessions stay safe.
 */
export interface WindowGeometry {
  width: number;
  height: number;
  x: number;
  y: number;
}

/**
 * Current window rect, or null while maximized (the maximized rect is the
 * monitor, not the user's geometry) and outside Tauri.
 */
export async function getWindowGeometry(): Promise<WindowGeometry | null> {
  try {
    const win = getCurrentWindow();
    if (await win.isMaximized()) return null;
    const scale = await win.scaleFactor();
    const size = await win.innerSize();
    const pos = await win.outerPosition();
    return {
      width: size.width / scale,
      height: size.height / scale,
      x: pos.x / scale,
      y: pos.y / scale,
    };
  } catch {
    return null;
  }
}

export async function applyWindowGeometry(g: WindowGeometry): Promise<void> {
  try {
    const win = getCurrentWindow();
    await win.setSize(new LogicalSize(g.width, g.height));
    await win.setPosition(new LogicalPosition(g.x, g.y));
  } catch {
    /* no webview / ACL denied → ignore */
  }
}

/**
 * Subscribe to resize + move events; `cb` fires on either. Resolves to an
 * unsubscribe function (identity no-op outside Tauri).
 */
export async function onWindowGeometryChanged(
  cb: () => void,
): Promise<() => void> {
  try {
    const win = getCurrentWindow();
    const unResized = await win.onResized(cb);
    const unMoved = await win.onMoved(cb);
    return () => {
      unResized();
      unMoved();
    };
  } catch {
    return () => undefined;
  }
}

/**
 * Properties inspector contract (docs/GUI_UX_SPEC.md §6, §10;
 * DESIGN_SYSTEM.md §21 "Inspector" inventory).
 *
 * The properties panel is a *contextual* inspector: it renders whatever the
 * current selection resolves to and stays closed while nothing is selected
 * (§6: 何も選択していない時、プロパティは原則閉じる). Feature teams supply
 * the selection → content mapping; the shell owns only visibility, sizing
 * and region placement — it must never hard-code feature inspectors here.
 */
export type InspectorContent =
  /** Nothing selected → panel closed by default; manual open shows the
      placeholder body. */
  | { kind: "none" }
  /** A canonical note is selected (UI-003 note IDs). Feature fields
      (pitch / spelling / onset / duration / measure / confidence /
      source position — protocol/copy properties.fields) are filled in by
      the note-inspector feature, not by this shell. */
  | { kind: "note"; noteId: string }
  /** A waveform/score range is selected. */
  | { kind: "range"; startSec: number; endSec: number };

export const NO_SELECTION: InspectorContent = { kind: "none" };

/** Whether the selection warrants auto-opening the panel (§6). */
export function inspectorHasContent(content: InspectorContent): boolean {
  return content.kind !== "none";
}

import { useCallback, useEffect, useState } from "react";

/**
 * Workspace layout state (docs/GUI_UX_SPEC.md §21 responsive, §26 session
 * restore).
 *
 * Breakpoints (window inner width, CSS px):
 *   >=1600  wide     properties docked 280–320px, full command labels
 *   1200–1599 medium  properties docked 240–280px, secondary labels icon化
 *   1100–1199 compact properties becomes an overlay drawer, less-frequent
 *                    commands move to overflow; score keeps priority
 *   <1100   not supported — the native window minimum (1100px) stops resize
 *           before this; the CSS min-width mirrors it as a deterministic
 *           floor so the layout can never compress below the spec.
 *
 * All resize math is clamp-based and deterministic: the stored value is the
 * user's *requested* size, the rendered size is always `clamp(requested,
 * breakpointRange)` — crossing a breakpoint re-clamps without losing the
 * request.
 */
export type LayoutBreakpoint = "wide" | "medium" | "compact";

export function breakpointForWidth(width: number): LayoutBreakpoint {
  if (width >= 1600) return "wide";
  if (width >= 1200) return "medium";
  return "compact";
}

/** Docked/overlay width limits per breakpoint (§21). */
export function propertiesRange(bp: LayoutBreakpoint): {
  min: number;
  max: number;
  fallback: number;
} {
  switch (bp) {
    case "wide":
      return { min: 280, max: 320, fallback: 296 };
    case "medium":
      return { min: 240, max: 280, fallback: 264 };
    case "compact":
      // Overlay drawer: §21 gives no explicit band; keep the same order of
      // magnitude so the drawer never dwarfs the score it floats over.
      return { min: 240, max: 320, fallback: 280 };
  }
}

export function clampPropertiesWidth(
  requested: number,
  bp: LayoutBreakpoint,
): number {
  const { min, max } = propertiesRange(bp);
  return Math.min(max, Math.max(min, Math.round(requested)));
}

/* Waveform vertical band (§8): standard 96–120, min 64, max ≈35% of the
   work area (waveform + score region height). The work area is the window
   minus fixed chrome rows (title 32 + command bar 44 + transport 52 +
   status 26 = 154). */
export const WAVEFORM_DEFAULT = 96;
export const WAVEFORM_MIN = 64;
export const WORKSPACE_CHROME_HEIGHT = 154;

export function waveformMaxHeight(windowHeight: number): number {
  return Math.max(
    WAVEFORM_MIN,
    Math.round((windowHeight - WORKSPACE_CHROME_HEIGHT) * 0.35),
  );
}

export function clampWaveformHeight(
  requested: number,
  windowHeight: number,
): number {
  return Math.min(
    waveformMaxHeight(windowHeight),
    Math.max(WAVEFORM_MIN, Math.round(requested)),
  );
}

/* ----------------------------- persistence ----------------------------- */

const STORAGE_KEY = "hornscribe.layout.v1";

interface PersistedLayout {
  propertiesOpen?: boolean;
  propertiesWidth?: number;
  waveformHeight?: number;
}

function loadLayout(): PersistedLayout {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as PersistedLayout;
    return typeof parsed === "object" && parsed !== null ? parsed : {};
  } catch {
    return {};
  }
}

function saveLayout(layout: PersistedLayout): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(layout));
  } catch {
    /* persistence is best-effort */
  }
}

/* ------------------------------- hooks -------------------------------- */

function useViewportSize(): { width: number; height: number } {
  const [size, setSize] = useState(() => ({
    width: window.innerWidth,
    height: window.innerHeight,
  }));
  useEffect(() => {
    const onResize = () =>
      setSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return size;
}

export interface WorkspaceLayout {
  breakpoint: LayoutBreakpoint;
  /** Whether the properties panel is rendered (§6: user-closable). */
  propertiesOpen: boolean;
  /** Effective (clamped) docked/overlay panel width in px. */
  propertiesWidth: number;
  /** Effective (clamped) waveform height in px. */
  waveformHeight: number;
  /** Panel/waveform bounds for the current breakpoint — these drive the
      separator aria-valuemin/max contract. */
  propertiesMin: number;
  propertiesMax: number;
  waveformMin: number;
  waveformMax: number;
  setPropertiesOpen(open: boolean): void;
  /** Request a new docked width; stored raw, rendered clamped. */
  requestPropertiesWidth(px: number): void;
  requestWaveformHeight(px: number): void;
  resetPropertiesWidth(): void;
  resetWaveformHeight(): void;
}

export function useWorkspaceLayout(): WorkspaceLayout {
  const [stored, setStored] = useState<PersistedLayout>(loadLayout);
  const viewport = useViewportSize();
  const breakpoint = breakpointForWidth(viewport.width);

  const update = useCallback((patch: PersistedLayout) => {
    setStored((prev) => {
      const next = { ...prev, ...patch };
      saveLayout(next);
      return next;
    });
  }, []);

  const range = propertiesRange(breakpoint);
  const propertiesWidth = clampPropertiesWidth(
    stored.propertiesWidth ?? range.fallback,
    breakpoint,
  );
  const waveformHeight = clampWaveformHeight(
    stored.waveformHeight ?? WAVEFORM_DEFAULT,
    viewport.height,
  );

  return {
    breakpoint,
    // §6: closed while nothing is selected; user can reopen via the
    // command-bar overflow menu. EMPTY never mounts the region at all.
    propertiesOpen: stored.propertiesOpen ?? false,
    propertiesWidth,
    waveformHeight,
    propertiesMin: range.min,
    propertiesMax: range.max,
    waveformMin: WAVEFORM_MIN,
    waveformMax: waveformMaxHeight(viewport.height),
    setPropertiesOpen: useCallback(
      (open: boolean) => update({ propertiesOpen: open }),
      [update],
    ),
    requestPropertiesWidth: useCallback(
      (px: number) => update({ propertiesWidth: px }),
      [update],
    ),
    requestWaveformHeight: useCallback(
      (px: number) => update({ waveformHeight: px }),
      [update],
    ),
    resetPropertiesWidth: useCallback(
      () => update({ propertiesWidth: propertiesRange(breakpoint).fallback }),
      [update, breakpoint],
    ),
    resetWaveformHeight: useCallback(
      () => update({ waveformHeight: WAVEFORM_DEFAULT }),
      [update],
    ),
  };
}

/**
 * Pointer drag-resize for the panel separators. `toValue` maps a pointer
 * position to the requested size; `apply` receives it on every move.
 * Keyboard resize is handled by the separators themselves via
 * `resizeKeyDelta` (±8px on the 4px grid).
 */
export function startPointerResize(
  e: React.PointerEvent,
  apply: (value: number) => void,
  toValue: (clientX: number, clientY: number) => number,
): void {
  e.preventDefault();
  const move = (ev: PointerEvent) => apply(toValue(ev.clientX, ev.clientY));
  const up = () => {
    window.removeEventListener("pointermove", move);
    window.removeEventListener("pointerup", up);
  };
  window.addEventListener("pointermove", move);
  window.addEventListener("pointerup", up);
}

/** Arrow-key resize delta for separators (grows on ←/↑, shrinks on →/↓). */
export function resizeKeyDelta(
  e: React.KeyboardEvent,
  base: number,
): number | null {
  if (e.key === "ArrowLeft" || e.key === "ArrowUp") return base - 8;
  if (e.key === "ArrowRight" || e.key === "ArrowDown") return base + 8;
  return null;
}

import type { CommandSnapshot } from "../commands/types";

/**
 * Workspace screen state machine (docs/GUI_UX_SPEC.md §27).
 *
 * The shell owns *which regions exist* for each state; feature code owns the
 * transitions (open audio → audioReady, transcribe → transcribing, …). For
 * UI-011 the live app still sits in `empty` (no file/engine plumbing yet),
 * but every state renders a correct layout so feature teams never invent
 * their own.
 *
 *   EMPTY ─open→ AUDIO_READY ─transcribe→ TRANSCRIBING
 *                                          ├ cancel → AUDIO_READY
 *                                          ├ fail   → TRANSCRIPTION_ERROR
 *                                          └ done   → SCORE_READY
 *   SCORE_READY ├ review → REVIEWING ├ export → EXPORTING └ retranscribe
 */
export type ScreenState =
  | "empty"
  | "audioReady"
  | "transcribing"
  | "scoreReady"
  | "reviewing"
  | "exporting";

export const SCREEN_STATES: readonly ScreenState[] = [
  "empty",
  "audioReady",
  "transcribing",
  "scoreReady",
  "reviewing",
  "exporting",
];

/**
 * Region visibility per state (§3 empty state shows none of the work
 * surfaces; §4+ show all once audio exists).
 */
export interface RegionVisibility {
  /** Waveform / timeline strip. */
  waveform: boolean;
  /** Score workspace region — always mounted (it carries the empty state). */
  score: boolean;
  /** Properties panel region — also gated by the user close/open toggle. */
  properties: boolean;
  /** Transport bar. */
  transport: boolean;
}

export function regionVisibility(screen: ScreenState): RegionVisibility {
  const loaded = screen !== "empty";
  return {
    waveform: loaded,
    score: true,
    // The panel itself decides open/closed; EMPTY never mounts it (§3).
    properties: loaded,
    transport: loaded,
  };
}

/**
 * Map the screen machine onto the UI-012 CommandSnapshot fields (§23) so
 * command enablement stays consistent: 採譜 needs audio and is disabled
 * while a transcription runs (§5), 要確認 needs a score with pending
 * issues, 書き出し needs a score. Playback/undo/selection fields are owned
 * by their feature issues, not by the screen machine.
 */
export function commandStateFor(
  screen: ScreenState,
): Pick<
  CommandSnapshot,
  "hasAudio" | "hasScore" | "isTranscribing" | "reviewOpen"
> {
  const hasScore =
    screen === "scoreReady" || screen === "reviewing" || screen === "exporting";
  return {
    hasAudio: screen !== "empty",
    hasScore,
    isTranscribing: screen === "transcribing",
    reviewOpen: screen === "reviewing",
  };
}

import {
  applyWindowGeometry,
  getWindowGeometry,
  onWindowGeometryChanged,
} from "../tauri/bridge";

/**
 * Window geometry persistence (docs/GUI_UX_SPEC.md §26).
 *
 * Layout state (panel sizes, visibility) lives in localStorage via
 * layout.ts; the native window size/position needs the webview ↔ shell
 * boundary, so it goes through tauri/bridge. Everything degrades to a no-op
 * in a plain browser dev session (invoke throws → caught in bridge).
 */

const STORAGE_KEY = "hornscribe.window.v1";

interface StoredGeometry {
  width: number;
  height: number;
  x: number;
  y: number;
}

function load(): StoredGeometry | null {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const g = JSON.parse(raw) as StoredGeometry;
    if (
      typeof g.width === "number" &&
      typeof g.height === "number" &&
      typeof g.x === "number" &&
      typeof g.y === "number"
    ) {
      return g;
    }
  } catch {
    /* fall through */
  }
  return null;
}

function save(g: StoredGeometry): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(g));
  } catch {
    /* best-effort */
  }
}

/**
 * Re-apply the persisted window geometry on startup and keep it updated
 * while the window lives. Size/position are stored in *logical* px so a
 * restored window lands at the same physical size under 150/200% scaling.
 * Returns an unsubscribe function.
 */
export async function initWindowGeometryPersistence(): Promise<() => void> {
  const stored = load();
  if (stored) {
    await applyWindowGeometry(stored);
  }

  let timer: number | undefined;
  const persistSoon = () => {
    window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      // While maximized the reported rect is the monitor — skip persisting
      // it so the restored size stays the user's normal geometry.
      void getWindowGeometry().then((g) => {
        if (g) save(g);
      });
    }, 400);
  };

  return onWindowGeometryChanged(persistSoon);
}
